async function loadPopulationPercentile(score){
  currentPercentile=null;
  const metric=$('percentile-metric'),note=$('percentile-note');
  try{
    const s=await getSession();
    if(!s?.token)return null;
    const resp=await fetch(API+'/reports/percentile',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${s.token}`},body:JSON.stringify({token:s.token,assessmentName:name,score})});
    const data=await resp.json();
    if(!resp.ok||data.status!=='success')throw new Error(data.message||'Percentile unavailable');
    currentPercentile=data;
    if(data.available){
      $('percentile-value').textContent=`${data.percentile}th`;
      $('percentile-sample').textContent=`Compared with ${data.populationSize} completed participants in ${name} · ${data.provisional?'provisional ':' '}population percentile`.replace(/\s+/g,' ').trim();
      metric?.classList.remove('hidden');
      if(note)note.textContent=`Pattern language remains developmental; the overall index also includes a ${data.provisional?'provisional ':''}population percentile based on ${data.populationSize} completed participants.`;
    }else{
      metric?.classList.add('hidden');
      if(note)note.textContent=`Pattern language is developmental. Population percentile activates when this assessment reaches ${data.minimumPopulation} completed participants; current population: ${data.populationSize}.`;
    }
    return data;
  }catch(e){
    metric?.classList.add('hidden');
    if(note)note.textContent='Pattern language is developmental. Population percentile is temporarily unavailable.';
    console.warn('Population percentile unavailable',e);
    return null;
  }
}
